import React from 'react';

export interface FluxioIconProps extends React.SVGProps<SVGSVGElement> {
  size?: number | string;
  className?: string;
  strokeWidth?: number;
}

function createFluxioIcon(
  displayName: string,
  paths: Array<{ d: string; tx?: number; ty?: number }>
) {
  const Component = React.forwardRef<SVGSVGElement, FluxioIconProps>(
    ({ size = 24, className = '', style, strokeWidth, ...props }, ref) => (
      <svg
        ref={ref}
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        className={`fluxio-icon ${className}`}
        style={{ display: 'inline-block', verticalAlign: 'middle', flexShrink: 0, ...style }}
        aria-hidden="true"
        {...props}
      >
        {paths.map((p, i) => (
          <path
            key={i}
            d={p.d}
            transform={p.tx || p.ty ? `translate(${p.tx || 0}, ${p.ty || 0})` : undefined}
            fill="currentColor"
          />
        ))}
      </svg>
    )
  );
  Component.displayName = displayName;
  return Component;
}

